extension UntrustedText: Equatable, Hashable {
    public static func ==(lhs: UntrustedText, rhs: UntrustedText) -> Bool {
        if lhs.raw != rhs.raw {
            return false
        }
        if lhs.display != rhs.display {
            return false
        }
        if lhs.hiddenRemoved != rhs.hiddenRemoved {
            return false
        }
        if lhs.whitespaceNormalised != rhs.whitespaceNormalised {
            return false
        }
        if lhs.truncated != rhs.truncated {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(raw)
        hasher.combine(display)
        hasher.combine(hiddenRemoved)
        hasher.combine(whitespaceNormalised)
        hasher.combine(truncated)
    }
}



