    public var scheme: String
    /**
     * Host, lowercase, punycoded, and bracketed when it is an IPv6 literal --
     * whatever a URL parser normalises it to, so two spellings of one host
     * cannot look like two hosts.
     */
    public var host: String
    /**
     * Absent when the scheme's default port is in use, so
     * `https://example.com` and `https://example.com:443` are one value.
     */
    public var port: UInt16?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * `http` or `https`, lowercase.
         */scheme: String, 
        /**
         * Host, lowercase, punycoded, and bracketed when it is an IPv6 literal --
         * whatever a URL parser normalises it to, so two spellings of one host
         * cannot look like two hosts.
         */host: String, 
        /**
         * Absent when the scheme's default port is in use, so
         * `https://example.com` and `https://example.com:443` are one value.
         */port: UInt16?) {
        self.scheme = scheme
        self.host = host
        self.port = port
    }
}

#if compiler(>=6)
extension WebOrigin: Sendable {}
#endif


extension WebOrigin: Equatable, Hashable {
    public static func ==(lhs: WebOrigin, rhs: WebOrigin) -> Bool {
        if lhs.scheme != rhs.scheme {
            return false
        }
        if lhs.host != rhs.host {
            return false
        }
        if lhs.port != rhs.port {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(scheme)
        hasher.combine(host)
        hasher.combine(port)
    }
}



